INSERT INTO `article` (`article_id`,`title`,`author`,`dynasty`,`content`,`translate`,`appreciate`,`notes`,`genre`,`source`) VALUES
('rd3_7_0','刘敬叔引诗','无名氏','南北朝','鸡山别飞响，
雉涧和清音。',NULL,'','{"preface": "《异苑》曰：朱文绣与罗子钟为友。俱仕于梁。绣既死。钟哀哭之。其夜俱亡。梁南七里有鸡山。葬绣于其中。北九里有雉涧。埋钟于其内。绣神灵变为雉。钟魂魄化为雉。清鸣哀响。来往一不绝。故《诗》云：", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_1','民间为谢灵运谣','无名氏','南北朝','四人挈衣裙，
三人捉坐席。',NULL,'','{"preface": "《宋书》曰：陈郡谢灵运。每出入。自扶接者常数人。民间谣曰云云。此盖不肃之咎。后坐诛。", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_2','元嘉中魏地童谣','无名氏','南北朝','轺车北来如穿雉。
不意虏马饮江水。
虏主北归石济死。
虏欲渡江天不徙。',NULL,'','{"preface": "南史曰：宋元嘉二十七年。魏太武帝围汝南戍。文帝遣臧质北救。至盱眙。太武已过淮。自广陵返攻盱眙。就质求酒。质封溲便与之。且报书云。不闻童谣言邪。虏马饮江水。佛狸死卯年。冥期使然。非复人事。尔智识及众岂能胜苻坚邪。顷年展尔陆梁者。是尔未饮江。太岁未卯耳。时魏地有童谣。故质引之云。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_3','臧质引童谣','无名氏','南北朝','虏马渡江水，
佛狸死卯年。',NULL,'','{"preface": "", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_4','元嘉末童谣','无名氏','南北朝','钱唐出天子。',NULL,'','{"preface": "高僧传曰：昙爽立寺。名新亭精舍。后孝武帝南下伐凶。銮旆至此寺。及登禅。复幸禅堂。故元嘉末童谣云云。乃禅堂之谓。故中兴禅房犹有龙飞殿焉。", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_5','民间为奚显度谣','无名氏','南北朝','宁得建康压额。
不能受奚度拍。',NULL,'','{"preface": "南史曰：大明中。有奚显度者为员外散骑侍郎。孝武尝使主领人功。而苛虐无道。动加捶挞。暑雨寒雪。不听暂休。人不堪命。时建康县考囚。或用方材压额及踝胫。故民间有此谣。又相戏曰：勿反顾。付奚度。其暴酷如此。", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_6','泰始中童谣','无名氏','南北朝','东城出天子。',NULL,'','{"preface": "南《齐书》曰：宋泰始中童谣云云。故明帝杀建安王休仁。苏侃云。后顺帝自东城即位。论者谓应之。乃是武进县上所居东城也。", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_7','永光初谣言','无名氏','南北朝','湘州出天子。',NULL,'','{"preface": "《宋书》曰：前废帝永光初。又谣言云云。幼主欲南幸湘川以厌之。既而湘东王即尊位。是为明帝。", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_8','元徽中童谣','无名氏','南北朝','襄阳白铜蹄。
郎杀荆州儿。',NULL,'','{"preface": "《齐书》曰：元徽中童谣。后沈攸之反。雍州刺史张敬儿袭江陵。杀攸之子元瑱等。", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_9','东阳为释慧约谣','无名氏','南北朝','少达妙理娄居士。',NULL,'','{"preface": "高僧传曰：释慧约姓娄氏。年二十始游于剡。远会素心。多究经典。故东阳谣曰：", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_10','时人为刘劭刘骏语','无名氏','南北朝','遥望建康城，
江水逆流萦。
前见子杀父，
后见弟杀兄。',NULL,'','{"preface": "《魏书》曰：义隆太子劭及始兴王休明等斩义隆。劭弟骏讨之。擒劭、休明并枭首大桁。男女一皆从戮。时人为之语曰：", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_11','麦城俗谚','无名氏','南北朝','东驴西磨。
麦城自破。',NULL,'','{"preface": "寰宇记曰：麦城东有驴城。沮水之西有磨城。犄角麦城。昔伍子胥造此二城以攻麦城。假驴磨之名。俗谚云。", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_12','颜延之引谚','无名氏','南北朝','富则盛。
贫则病。',NULL,'','{"preface": "《宋书》曰：延之为庭诰之文曰：富厚贫薄。事之悬也。谚曰：", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_13','清溪谚','无名氏','南北朝','扬州青。
是鬼营。',NULL,'','{"preface": "《异苑》曰：檀道济居青溪。第二儿夜忽见人来缚己。欲呼不得。至晓乃解。犹见绳痕。先是吴将步阐所居。谚云云云。青溪。青扬是也。自步及檀。皆被诛。", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_14','释慧通引谚','无名氏','南北朝','指南为北，
自谓不惑。
指西为东，
自谓不蒙。',NULL,'','{"preface": "弘明集曰：释慧通驳顾道士夷夏论曰：谚曰：", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_7_15','时人为丁旿语','无名氏','南北朝','勿跋扈。
付丁旿。',NULL,'','{"preface": "《宋书》武帝纪曰：诸葛长民贪淫骄纵。帝每优容之。刘毅既诛。长民惧祸。及将谋作乱。帝自江陵还。长民到门。引前却人閒语。帝已密命左右丁旿自幔后于坐拉焉。死床侧。舆尸付廷尉。旿骁勇有力。时人语曰：", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_16','南豫州军士为王玄谟宗越语','无名氏','南北朝','宁作五年徒，
不逢王玄谟。
玄谟犹尚可，
宗越更杀我。',NULL,'','{"preface": "《宋书》曰：玄谟性严克少恩。而将军宗越御下更苛酷。军士为之语曰：", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_17','鼓山俗语','无名氏','南北朝','南彭北鼓。
相去十五。',NULL,'','{"preface": "宋永初古今山川记曰：鼓山有石鼓形二所。南北相当。俗语云。", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_18','京邑为何勖孟灵休语','无名氏','南北朝','安成食。
临汝饰。',NULL,'','{"preface": "《宋书》曰：时安成公何勖。无忌之子也。临汝公孟灵休。昶之子也。并各奢豪。与湛之共以肴膳器服车马相尚。京邑为之语曰：", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_19','时人为王延之王僧虔语','无名氏','南北朝','二王居平。
不送不迎。',NULL,'','{"preface": "南《齐书》曰：齐高帝辅政。朝野之情。人怀彼此。延之与尚书令王僧虔中立无所去就。时人语曰云云。高帝以此善之。", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_20','京师为东安斗场二寺僧语','无名氏','南北朝','斗场禅师窟，
东安谈义林。',NULL,'','{"preface": "《宋书》曰：慧严、慧义道人并在安东寺。学行精整。为道俗所推。时斗场寺多禅僧。京师为之语曰：", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_21','时人为胡母颢语','无名氏','南北朝','禾绢闭眼诺。
胡母大张橐。',NULL,'','{"preface": "南史曰：宋明帝时。阮佃夫、杨运长、王道隆皆擅威权。言为诏敕。君守令长。一缺十除。内外混然。官以贿命。王阮家富于公室。中书舍人胡母颢专权。奏无不可。时人语云云。禾绢谓上也。", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_22','百姓为袁粲褚彦回语','无名氏','南北朝','可怜石头城。
宁为袁粲死。
不作褚渊生。',NULL,'','{"preface": "南史曰：袁粲谋举兵诛齐高帝。褚渊发其谋。粲兵败过害。而渊独辅政。于时百姓语曰：", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_23','齐宋以来民间语','无名氏','隋','扰攘建武上。',NULL,'','{"preface": "南《齐书》曰：齐、宋以来民间语云云。明帝初。诛害蕃戚。京师危骇。", "note": ""}','句','hefengbao/jingmo-data3'),
('rd3_7_24','时人评八僧语','无名氏','南北朝','生睿发天真，
严观洼流得。
慧义彭亨进，
寇渊于默塞。',NULL,'','{"preface": "高僧传曰：宋长安龙光寺有竺道生。本姓魏。钜鹿人也。性广机警。神气清穆。初生与睿公及严观同学齐名。故时人评曰：", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_25','时人为释道经慧静语','无名氏','南北朝','洛下长大耳，
东阿黑如墨。
有问无不酬，
有酬无不塞。',NULL,'','{"preface": "高僧传曰：释慧静姓王。东阿人。容甚黑。而机悟清远。时洛中有沙门道经。亦解迈当时。与慧静齐合。而耳甚长大。故时人语曰：", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_26','碧玉歌','无名氏','南北朝','碧玉破瓜时，
郎为情颠倒。
芙蓉陵霜荣，
秋容故尚好。',NULL,'','{"preface": "《诗纪》云。左克明作古辞。乐苑曰：碧玉歌者。宋汝南王之所作也。碧玉。汝南王妾名。以宠爱之甚。所以歌之。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_27','华山畿二十五首','无名氏','隋','闻欢大养蚕，
定得几许丝。
所得何足言，
奈何黑瘦为。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_28','华山畿二十五首','无名氏','隋','夜相思。
投壶不得箭。
忆欢作娇时。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_29','华山畿二十五首','无名氏','隋','开门枕水渚。
三刀治一鱼。
历乱伤杀汝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_30','华山畿二十五首','无名氏','隋','未敢便相许。
夜闻侬家论。
不持侬与汝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_31','华山畿二十五首','无名氏','隋','懊恼不堪止。
上床解要绳。
自经屏风里。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_32','华山畿二十五首','无名氏','隋','将懊恼。
石阙昼夜题。
碑泪常不燥。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_33','华山畿二十五首','无名氏','隋','别后常相思。
顿书千丈阙。
题碑无罢时。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_34','华山畿二十五首','无名氏','隋','奈何许。
所欢不在间。
娇笑向谁绪。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_35','华山畿二十五首','无名氏','隋','隔津欢。
牵牛语织女。
离泪溢河汉。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_36','华山畿二十五首','无名氏','隋','啼相忆。
泪如漏刻水。
昼夜流不息。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_37','华山畿二十五首','无名氏','隋','著处多遇罗。
的的往年少。
艳情何能多。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_38','华山畿二十五首','无名氏','隋','无故相然我。
路绝行人断。
夜夜故望汝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_39','华山畿二十五首','无名氏','隋','一坐复一起。
黄昏人定后。
许时不来已。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_40','华山畿二十五首','无名氏','隋','摩可浓。
巷巷相罗截。
终当不置汝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_41','华山畿二十五首','无名氏','隋','不能久长离。
中夜忆欢时。
抱被空中啼。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_42','华山畿二十五首','无名氏','隋','腹中如汤灌。
肝肠寸寸断。
教侬底聊赖。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_43','华山畿二十五首','无名氏','隋','相送劳劳渚。
长江不应满。
是侬泪成许。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_44','华山畿二十五首','无名氏','隋','郎情难可道。
欢行豆挟心。
见荻多欲绕。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_45','华山畿二十五首','无名氏','隋','松上萝。
愿君如行云。
时时见经过。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_46','华山畿二十五首','无名氏','隋','夜相思。
风吹窗帘动。
言是所欢来。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_47','华山畿二十五首','无名氏','隋','长鸣鸡。
谁知侬念汝。
独向空中啼。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_48','华山畿二十五首','无名氏','隋','腹中如乱丝。
愦愦适得去。
愁毒已复来。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_49','读曲歌八十九首','无名氏','南北朝','花钗芙蓉髻，
双鬓如浮云。
春风不知著，
好来动罗裙。',NULL,'','{"preface": "《宋书》乐志曰：读曲歌者。民间为彭城王义康所作也。其歌云。死罪刘领军。误杀刘第四。是也。古今乐录曰：读曲歌者。元嘉十七年。袁后崩。百官不敢作声歌。或因酒燕。止窃声读曲细吟而已。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_50','读曲歌八十九首','无名氏','隋','念子情难有。
已恶动罗裙。
斩侬入怀不。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_51','读曲歌八十九首','无名氏','隋','红蓝与芙蓉，
我色与欢敌。
莫案石榴花，
历乱听侬摘。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_52','读曲歌八十九首','无名氏','隋','千叶红芙蓉，
照灼绿水边。
馀花任郎摘，
慎莫罢侬连。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_53','读曲歌八十九首','无名氏','隋','思欢久。
不爱独枝莲。
只惜同心藕。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_54','读曲歌八十九首','无名氏','隋','打坏木栖床，
谁能坐相思。
三更书石阙，
忆子夜啼碑。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_55','读曲歌八十九首','无名氏','隋','奈何不可言。
朝看莫牛迹。
知是宿蹄痕。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_56','读曲歌八十九首','无名氏','隋','娑拖何处归，
道逢播掿郎。
口朱脱去尽，
花钗复低昂。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_57','读曲歌八十九首','无名氏','隋','所欢子。
莲从胸上度。
刺忆庭欲死。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_58','读曲歌八十九首','无名氏','隋','揽裳踱。
跣把丝织履。
故交白足露。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_59','读曲歌八十九首','无名氏','隋','上知所。
所欢不见怜。
憎状从前度。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_60','读曲歌八十九首','无名氏','隋','思难忍。
络罂语犹壶。
倒写侬顿尽。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_61','读曲歌八十九首','无名氏','隋','上树摘桐花，
何悟枝枯燥。
迢迢空中落，
遂为梧子道。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_62','读曲歌八十九首','无名氏','隋','縠衫两袖裂，
花钗鬓边低。
何处分别归，
西上古馀啼。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_63','读曲歌八十九首','无名氏','隋','所欢子。
不与他人别。
啼是忆郎耳。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_64','读曲歌八十九首','无名氏','隋','披被树明灯，
独思谁能忍。
欲知长寒夜，
兰灯倾壶尽。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_65','读曲歌八十九首','无名氏','隋','坐起叹汝好。
愿他甘丛香。
倾筐入怀抱。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_66','读曲歌八十九首','无名氏','隋','忆欢不能食。
徘徊三路间。
因风觅消息。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_67','读曲歌八十九首','无名氏','隋','朝日光景开，
从君良燕游。
愿如卜者策，
长与千岁龟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_68','读曲歌八十九首','无名氏','隋','所欢子。
问春花可怜。
括插袮裆里。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_69','读曲歌八十九首','无名氏','隋','芳萱初生时，
知是无忧草。
双眉画未成，
那能就郎抱。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_70','读曲歌八十九首','无名氏','隋','百花鲜。
谁能怀春日。
独入罗帐眠。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_71','读曲歌八十九首','无名氏','隋','闻欢得新侬。
四支懊如垂。
鸟散放行路。
井中百翅不能飞。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_72','读曲歌八十九首','无名氏','隋','怜欢敢唤名，
念欢不呼字。
连唤欢复欢，
两誓不相弃。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_73','读曲歌八十九首','无名氏','隋','白门前。
乌帽白帽来。
白帽郎是侬。
良不知乌帽郎是谁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_74','读曲歌八十九首','无名氏','隋','初阳正二月，
草木郁青青。
蹑履步前园，
时物感人情。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_75','读曲歌八十九首','无名氏','隋','青幡起御路，
绿柳荫驰道。
欢赠玉树筝，
侬送千金宝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_76','读曲歌八十九首','无名氏','隋','桃花落已尽，
秋思犹未央。
春风难期信，
托情明月光。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_77','读曲歌八十九首','无名氏','隋','计约黄昏后，
人断犹未来。
闻欢开方局，
已复将谁期。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_78','读曲歌八十九首','无名氏','隋','自从别郎后，
卧宿头不举。
飞龙落药店，
骨出只为汝。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_79','读曲歌八十九首','无名氏','隋','日光没已尽，
宿鸟纵横飞。
徙倚望行云，
躞蹀待郎归。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_80','读曲歌八十九首','无名氏','隋','百度不一回，
千书信不归。
春风吹杨柳，
华艳空徘徊。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_81','读曲歌八十九首','无名氏','隋','音信阔弦朔，
方悟千里遥。
朝霜语白日，
知我为欢消。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_82','读曲歌八十九首','无名氏','隋','合冥过藩来，
向晓开门去。
欢取身上好，
不为侬作虑。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_83','读曲歌八十九首','无名氏','隋','五鼓起开门，
正见欢子度。
何处宿行还，
衣被有霜露。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_84','读曲歌八十九首','无名氏','隋','本自无此意，
谁交郎举前。
视侬转迈迈，
不复来时言。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_85','读曲歌八十九首','无名氏','隋','自我别欢后，
叹音不绝响。
茱萸持捻泥，
龛有杀子像。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_86','读曲歌八十九首','无名氏','隋','家贫近店肆，
出入引长事。
郎君不浮华，
谁能呈实意。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_87','读曲歌八十九首','无名氏','隋','念日行不遇，
道逢播掿郎。
查灭衣服坏，
白肉亦黯疮。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_88','读曲歌八十九首','无名氏','隋','歔欷暗中啼，
斜日照帐里。
无油何所苦，
但使天明尔。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_89','读曲歌八十九首','无名氏','隋','黄丝咡素琴，
泛弹弦不断。
百弄任郎作，
唯莫广陵散。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_90','读曲歌八十九首','无名氏','隋','诈我不出门，
冥就他侬宿。
鹿转方相头，
丁倒欺人目。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_91','读曲歌八十九首','无名氏','隋','欢但且还去，
遗信相参伺。
契儿向高店，
须臾侬自来。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_92','读曲歌八十九首','无名氏','隋','欲行一过心，
谁我道相怜。
摘菊持饮酒，
浮华著口边。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_93','读曲歌八十九首','无名氏','隋','语我不游行，
常常走巷路。
败桥语方相，
欺侬那得度。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_94','读曲歌八十九首','无名氏','隋','阔面行负情，
诈我言端的。
画背作天图，
子将负星历。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_95','读曲歌八十九首','无名氏','隋','君行负怜事，
那得厚相于。
麻纸语三葛，
我薄汝粗疏。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_96','读曲歌八十九首','无名氏','隋','黄天不灭解，
甲夜曙星出。
漏刻无心肠，
复令五更毕。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_97','读曲歌八十九首','无名氏','隋','空中人。
住在高樯深閤里。
书信了不通。
故使风往尔。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_98','读曲歌八十九首','无名氏','隋','侬心常慊慊，
欢行由豫情。
雾露隐芙蓉，
见莲讵分明。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_99','读曲歌八十九首','无名氏','隋','非欢独慊慊，
侬意亦驱驱。
双灯俱时尽，
奈许两无由。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_100','读曲歌八十九首','无名氏','隋','谁交强缠绵，
常持罢作虑。
作生隐藕叶，
莲侬在何处。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_101','读曲歌八十九首','无名氏','隋','相怜两乐事，
黄作无趣怒。
合散无黄连，
此事复何苦。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_102','读曲歌八十九首','无名氏','隋','谁交强缠绵，
常持罢作意。
走马织悬帘，
薄情奈当驶。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_103','读曲歌八十九首','无名氏','隋','百忆却欲噫，
两眼常不燥。
蕃师五鼓行，
离侬何太早。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_104','读曲歌八十九首','无名氏','隋','含笑来向侬，
一抱不能置。
领后千里带，
那顿谁多媚。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_105','读曲歌八十九首','无名氏','隋','欢相怜。
今去何时来。
裲裆别去年。
不忍见分题。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_106','读曲歌八十九首','无名氏','隋','欢相怜。
题心共饮血。
流头入黄泉。
分作两死计。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_107','读曲歌八十九首','无名氏','隋','娇笑来向侬，
一抱不能已。
湖燥芙蓉萎，
莲汝藕欲死。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_108','读曲歌八十九首','无名氏','隋','欢心不相怜，
慊苦竟何已。
芙蓉腹里萎，
莲汝从心起。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_109','读曲歌八十九首','无名氏','隋','下帷掩灯烛，
明月照帐中。
无油何所苦，
但使天明侬。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_110','读曲歌八十九首','无名氏','隋','执手与欢别，
欲去情不忍。
馀光照已藩，
坐见离日尽。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_111','读曲歌八十九首','无名氏','隋','种莲长江边，
藕生黄蘖浦。
必得莲子时，
流离经辛苦。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_112','读曲歌八十九首','无名氏','隋','人传我不虚，
实情明把纳。
芙蓉万层生，
莲子信重沓。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_113','读曲歌八十九首','无名氏','隋','闻乖事难怀，
况复临别离。
伏龟语石板，
方作千岁碑。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_114','读曲歌八十九首','无名氏','隋','钤荡与时竞，
不得寻倾虑。
春风扇芳条，
常念花落去。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_115','读曲歌八十九首','无名氏','隋','坐倚无精魂，
使我生百虑。
方局十七道，
期会是何处。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_116','读曲歌八十九首','无名氏','隋','十期九不果，
常抱怀恨生。
然灯不下炷，
有油那得明。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_117','读曲歌八十九首','无名氏','隋','自从近日来，
了不相寻博。
竹帘裲裆题，
知子心情薄。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_118','读曲歌八十九首','无名氏','隋','下帷灯火尽，
朗月照怀里。
无油何所苦，
但今天明尔。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_119','读曲歌八十九首','无名氏','隋','近日莲违期，
不复寻博子。
六筹翻双鱼，
都成罢去已。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_120','读曲歌八十九首','无名氏','隋','侬亦粗经风。
罢顿葛帐里。
败许粗疏中。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_121','读曲歌八十九首','无名氏','隋','紫草生湖边，
误落芙蓉里。
色分都未获，
空中染莲子。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_122','读曲歌八十九首','无名氏','隋','闺閤断信使，
的的两相忆。
譬如水上影，
分明不可得。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_123','读曲歌八十九首','无名氏','隋','逍遥待晓分，
转侧听更鼓。
明月不应停，
特为相思苦。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_124','读曲歌八十九首','无名氏','隋','罢去四五年，
相见论故情。
杀荷不断藕，
莲心已复生。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_125','读曲歌八十九首','无名氏','隋','辛苦一朝欢，
须臾情易厌。
行膝点芙蓉，
深莲非骨念。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_126','读曲歌八十九首','无名氏','隋','慊苦忆侬欢，
书作后非是。
五果林中度，
见花多忆子。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_127','石城乐','无名氏','隋','阳春百花生，
摘插环髻前。
捥指蹋忘愁，
相与及盛年。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_128','石城乐','无名氏','隋','布帆百馀幅，
环环在江津。
执手双泪落，
何时见欢还。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_129','石城乐','无名氏','隋','大艑载三千，
渐水丈五馀。
水高不得渡，
与欢合生居。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_130','莫愁乐','无名氏','南北朝','莫愁在何处，
莫愁石城西。
艇子打两桨，
催送莫愁来。',NULL,'','{"preface": "《唐书》乐志曰：莫愁乐者，出于石城乐。石城有女子名莫愁。善歌谣。石城乐和中复有忘愁声。因有此歌。《古今乐录》曰：莫愁乐。亦云蛮乐。旧舞十六人。梁八人。《乐府解题》曰：古歌亦有莫愁洛阳女。与此不同。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_131','莫愁乐','无名氏','隋','闻欢下扬州，
相送楚山头。
探手抱腰看，
江水断不流。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_132','乌夜啼','无名氏','隋','辞家远行去，
侬欢独离居。
此日无啼音，
裂帛作还书。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_7_133','乌夜啼','无名氏','隋','可怜乌臼鸟，
强言知天曙。
无故三更啼，
欢子冒暗去。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_7_134','乌夜啼','无名氏','隋','乌生如欲飞，
飞飞各自去。
生离无安心，
夜啼至天曙。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_7_135','乌夜啼','无名氏','隋','笼窗窗不开，
荡户户不动。
欢下葳蕤龠，
交侬那得往。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_7_136','乌夜啼','无名氏','隋','远望千里烟，
隐当在欢家。
欲飞无两翅，
当奈独思何。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_7_137','乌夜啼','无名氏','隋','巴陵三江口，
芦荻齐如麻。
执手与欢别，
痛切当奈何。',NULL,'','{"preface": "", "note": ""}','乐府曲辞','hefengbao/jingmo-data3'),
('rd3_7_138','襄阳乐','无名氏','隋','上水郎担篙，
下水摇双橹。
四角龙子幡，
环环江当柱。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_139','襄阳乐','无名氏','隋','江陵三千三，
西塞陌中央。
但问相随否，
何计道里长。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_140','襄阳乐','无名氏','隋','人言襄阳乐，
乐作非侬处。
乘星冒风流，
还侬扬州去。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_141','襄阳乐','无名氏','隋','烂漫女萝草，
结曲绕长松。
三春虽同色，
岁寒非处侬。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_142','襄阳乐','无名氏','隋','扬州蒲锻环，
百钱两三丛。
不能买将还，
空手揽抱侬。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_143','襄阳乐','无名氏','隋','恶见多情欢，
罢侬不相语。
莫作乌集林，
忽如提侬去。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_144','寿阳乐','无名氏','南北朝','可怜八公山。
在寿阳。
别后莫相忘。',NULL,'','{"preface": "左云。古辞。古今乐录曰：寿阳乐者。宋南平穆王为豫州所作也。旧舞十六人。梁八人。○《诗纪》云。按其歌辞。盖叙伤别望归之思。南平穆王即刘铄也。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_145','寿阳乐','无名氏','隋','东台百馀尺。
凌风云。
别后不忘君。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_146','寿阳乐','无名氏','隋','梁长曲水流。
明如镜。
双林与郎照。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_147','寿阳乐','无名氏','隋','辞家远行去。
空为君。
明知岁月驶。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_148','寿阳乐','无名氏','隋','笼窗取凉风。
弹素琴。
一叹复一吟。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_149','寿阳乐','无名氏','隋','夜相思。
望不来。
人乐我独愁。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_150','寿阳乐','无名氏','隋','长淮何烂漫。
路悠悠。
得当乐忘忧。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_151','寿阳乐','无名氏','隋','上我长濑桥。
望归路。
秋风停欲度。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_152','寿阳乐','无名氏','隋','衔泪出伤门。
寿阳去。
必还当几载。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_153','西乌夜飞','无名氏','隋','暂请半日给，
徙倚娘店前。
目作宴瑱饱，
腹作宛恼饥。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_154','西乌夜飞','无名氏','隋','我昨忆欢时，
揽刀持自刺。
自刺分应死，
刀作杂楼僻。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_155','西乌夜飞','无名氏','隋','感郎崎岖情，
不复自顾虑。
臂绳双入结，
遂成同心去。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_156','宋南郊登歌三首','颜延之','南朝宋','夤威宝命，
严恭帝祖。
表海炳岱，
系唐胄楚。
灵鉴浚文，
民属睿武。
奄受敷锡，
宅中拓宇。
亘地称皇，
罄天作主。
月竁来宾，
日际奉土。
开元正首，
礼乐交举。
六典联事，
九官列序。
有牷在涤，
有洁在俎。
以荐王衷，
以答神祜。',NULL,'','{"preface": "《宋书》乐志曰：文帝元嘉二十二年。韶颜延之造天地郊夕牲、迎送神、飨神雅乐登歌三篇。", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_7_157','宋南郊登歌三首','颜延之','南朝宋','维圣飨帝，
维孝飨亲。
皇乎备矣，
有事上春。
礼行宗祀，
敬达郊礼。
金枝中树，
广乐四陈。
陟配在京，
降德在民。
奔精照夜，
高燎炀晨。
阴明浮烁，
沈咏深沦。
告成大报，
受釐元神。
月御按节，
星驱扶轮。
遥兴远驾，
曜曜振振。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_7_158','宋南郊登歌三首','颜延之','南朝宋','营泰畤，
定天衷。
思心睿，
谋筮从。
建表蕝，
设郊宫。
田烛置，
爟火通。
历元旬，
律首吉。
饰紫坛，
坎列室。
中星兆，
六宗秩。
乾宇晏，
地区谧。
大孝昭，
祭礼供。
牲日展，
盛自躬。
具陈器，
备礼容。
形舞缀，
被歌钟。
望帝阍，
耸神跸。
灵之来，
辰光溢。
洁粢酌，
娱太一。
明辉夜，
华皙日。
祼既始，
献又终。
烟芗鬯，
报清穹。
飨宋德，
祚王功。
休命永，
福履充。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_159','宋明堂歌九首','谢庄','南朝宋','地纽谧，
乾枢回。
华盖动，
紫微开。
旌蔽日，
车若云。
驾六龙，
乘絪缊。
晔帝京，
辉天邑。
圣祖降，
五灵集。
构瑶戺，
耸珠帘。
汉拂幌，
月栖檐。
舞缀畅，
钟石融。
驻飞景，
郁行风。
懋粢盛，
洁牲牷。
百礼肃，
群司虔。
皇德远，
大孝昌。
贯九幽，
洞三光。
神之安，
解玉銮。
景福至，
万寓欢。',NULL,'','{"preface": "通典曰：孝武建元元年。使谢庄造郊庙舞乐、明堂诸乐歌诗。南《齐书》乐志曰：明堂祠五帝。汉郊祀歌皆四言。宋孝武使谢庄造辞。庄依五行数。木数用三。火数用七。土数用五。金数用九。水数用六。周颂我将祀文王言皆四。其一句五。一句七。庄歌太祖亦无定句。", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_160','宋明堂歌九首','谢庄','南朝宋','雍台辨朔，
泽宫练辰。
洁火夕照，
明水朝陈。
六瑚贲室，
八羽华庭。
昭事先圣，
怀濡上灵。
肆夏戒敬，
升歌发德。
永固鸿基，
以绥万国。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_7_161','宋明堂歌九首','谢庄','南朝宋','维天为大。
维圣祖是则。
辰居万宇。
缀旒下国。
内灵八辅。
外光四瀛。
蒿宫仰盖。
日馆希旌。
复殿留景。
重檐结风。
刮楹接纬。
达响承虹。
设业设虚。
在王庭。
肇禋祀。
克配乎灵。
我将我享。
维孟之春。
以孝以敬。
以立我烝民。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_162','宋明堂歌九首','谢庄','南朝宋','参映夕，
驷照晨。
灵乘震，
司青春。
雁将向，
桐始蕤。
柔风舞，
暄光迟。
萌动达，
万品新。
润无际，
泽无垠。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_163','宋明堂歌九首','谢庄','南朝宋','龙精初见大火中，
朱光北至圭景同。
帝在在离寔司衡，
水雨方降木槿荣。
庶物盛长咸殷阜，
恩覃四冥被九有。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_164','宋明堂歌九首','谢庄','南朝宋','履建宅中宇，
司绳御四方。
裁化遍寒燠，
布政周炎凉。
景丽条可结，
霜明冰可折。
凯风扇朱辰，
白云流素节。
分至乘结晷，
启闭集恒度。
帝运缉万有，
皇灵澄国步。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_165','宋明堂歌九首','谢庄','南朝宋','百川如镜。
天地爽且明。
云冲气举。
德盛在素精。
木叶初下。
洞庭始扬波。
夜光彻地。
翻霜照悬河。
庶类收成。
岁功行欲宁。
浃地奉渥。
罄宇承秋灵。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_166','宋明堂歌九首','谢庄','南朝宋','岁月既晏方驰。
灵乘坎德司规。
玄云合晦鸟路。
白云繁亘天涯。
雷在地。
时未光。
饰国典。
闭关梁。
四节遍。
万物殿。
福九域。
祚八乡。
晨晷促。
夕漏延。
太阴极。
微阳宣。
鹊将巢。
冰已解。
气濡水。
风动泉。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_167','宋明堂歌九首','谢庄','南朝宋','蕴礼容，
馀乐度。
灵方留，
景欲暮。
开九重，
肃五达。
凤参差，
龙已秣。
云既动，
河既梁。
万里照，
四空香。
神之车，
归清都。
璇庭寂，
玉殿虚。
浚化凝，
孝风炽。
顾灵心，
结皇思。',NULL,'','{"preface": "", "note": ""}','古风','hefengbao/jingmo-data3'),
('rd3_7_168','宋宗庙登歌八首','无名氏','南北朝','绵绵遐绪，
明昭载融。
汉德未远，
尧有遗风。
于穆皇祖，
永世克隆。
本支惟庆，
贻厥靡穷。',NULL,'','{"preface": "《宋书》乐志曰：武帝永初中。诏庙乐用王韶之所造七庙登歌七首。又有七庙享神登歌一首。并以歌章太后。其辞亦韶之造。", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_7_169','宋宗庙登歌八首','无名氏','南北朝','乃立清庙，
清庙肃肃。
乃备礼容，
礼容穆穆。
显允皇祖，
昭是嗣服。
锡兹繁祉，
聿怀多福。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_7_170','宋宗庙登歌八首','无名氏','南北朝','四县既序，
箫管既举。
堂献六瑚，
庭万八羽。
先王有典，
克禋皇祖。
不显洪烈，
永介休祜。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_7_171','宋宗庙登歌八首','无名氏','南北朝','钟鼓喤喤，
威仪将将。
温恭礼乐，
致享曾皇。
迈德垂仁，
系轨重光。
天命纯嘏，
惠我无疆。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_7_172','宋宗庙登歌八首','无名氏','南北朝','铄矣皇祖，
帝度其心。
永言配命，
播兹徽音。
思我茂猷，
如玉如金。
骏奔在陛，
是鉴是歆。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_7_173','宋宗庙登歌八首','无名氏','南北朝','烝哉孝皇，
齐圣广渊。
发祥诞庆，
景祚自天。
德敷金石，
道被管弦。
有命既集，
徽风永宣。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_7_174','宋宗庙登歌八首','无名氏','南北朝','惟天有命，
眷求上哲。
赫矣圣武，
抚运桓扰。
功并敷土，
道均汝坟。
止戈曰武，
经纬称文。
鸟龙失纪，
云火代名。
受终改物，
作我宋京。
至道惟王，
大业有劭。
降德兆民，
升歌清庙。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_7_175','宋宗庙登歌八首','无名氏','南北朝','奕奕寝庙，
奉璋在庭。
笙龠既列，
牺象既盈。
黍稷匪芳，
明祀惟馨。
乐具礼充，
洁羞荐诚。
神之格思，
介以休祯。
济济群辟，
永观厥成。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_7_176','宋世祖庙歌二首','谢庄','南朝宋','帝锡二祖，
长世多祜。
于穆睿考，
龚圣承矩。
玄极驰驭，
乾纽坠绪。
辟我皇维，
缔我宋宇。
刷定四海，
肇构神京。
复礼辑乐，
散马堕城。
泽牣九有，
化浮八瀛。
庆云承掖，
甘露飞甍。
肃肃清庙，
徽徽閟宫。
舞蹈象德，
笙磬陈风。
黍稷非盛，
明德惟崇。
神其歆止，
降福无穷。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_7_177','宋世祖庙歌二首','谢庄','南朝宋','禀祥月辉，
毓德轩光。
嗣徽妫汭，
思媚周姜。
母临万宇，
训蔼紫房。
朱玄玉龠，
式载琼芳。',NULL,'','{"preface": "", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_7_178','宋章庙乐舞歌十五首','殷淡','南朝宋','彝承孝典，
恭事严圣。
浃天奉赆，
罄壤齐庆。
司仪具序，
羽容夙彰。
芬枝飏烈，
黼构周张。
助宝奠轩，
酎珍充庭。
璆县凝会，
琄朱伫声。
先期选礼，
肃若有承。
祗对灵祉，
皇庆昭膺。',NULL,'','{"preface": "宋章乐志曰：章庙乐舞杂歌悉同用太庙辞。唯三后别撰。○梁天监元年。周舍议曰：《周礼》。王出入奏王夏。大祭祀与朝会同。而汉制皇帝在朝奏永至。朝会别奏皇夏。二乐有异。于礼为乖。乃除永至。还用皇夏。盖秦、汉以来称皇。故变王夏为皇夏也。又礼。尸出入奏肆夏。宾入大门奏肆夏。牲出入奏昭夏。宋季失礼。神入庙门遂奏昭夏。乃以牲牢之乐。用接祖考之灵。斯皆前代之深疵。当今所宜改也。殷淡。字夷远。陈郡长平人。历黄门吏部郎、太子中庶子、步兵校尉。大明中。以文章见知。为当时才士。", "note": ""}','四言诗','hefengbao/jingmo-data3'),
('rd3_7_179','宋章庙乐舞歌十五首','殷淡','南朝宋','尊事威仪，
辉容昭叙。
迅恭神明，
粢盛牲俎。
肃肃严宫，
蔼蔼崇基。
皇灵降祉，
百祗具司。
戒诚望夜，
端列承朝。
依微昭旦，
物色轻宵。
鸿庆遐鬯，
嘉荐令芳。
翊帝明德，
